,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'u-colors:t-Cards--basic:t-Cards--displayIcons:t-Cards--4cols:t-Cards--animColorFill'
