,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Total Clubs'' AS CARD_TITLE,',
'       TO_CHAR((SELECT COUNT(*) FROM CLUB)) AS CARD_TEXT,',
'       ''Active clubs on campus'' AS CARD_SUBTEXT,',
'       ''fa-building'' AS CARD_ICON',
'FROM DUAL',
'UNION ALL',
'SELECT ''Total Members'' AS CARD_TITLE,',
'       TO_CHAR((SELECT COUNT(*) FROM MEMBER)) AS CARD_TEXT,',
'       ''Registered students'' AS CARD_SUBTEXT,',
'       ''fa-users'' AS CARD_ICON',
'FROM DUAL',
'UNION ALL',
'SELECT ''Total Events'' AS CARD_TITLE,',
'       TO_CHAR((SELECT COUNT(*) FROM EVENT)) AS CARD_TEXT,',
'       ''Events organized'' AS CARD_SUBTEXT,',
'       ''fa-calendar'' AS CARD_ICON',
'FROM DUAL',
'UNION ALL',
'SELECT ''Total Budget'' AS CARD_TITLE,',
'       TO_CHAR((SELECT SUM(TOTALAMOUNT) FROM BUDGET)) AS CARD_TEXT,',
'       ''Total allocated funds'' AS CARD_SUBTEXT,',
'       ''fa-money'' AS CARD_ICON',
'FROM DUAL'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
